const Autobase = require('autobase')
const Hyperbee = require('hyperbee')
const b4a = require('b4a')
const make_emitter = require('make-emitter')

module.exports = settings_store
module.exports.get_writer_key = get_writer_key

// the synced settings: an encrypted autobase, its view is a hyperbee with
// dconf/<key> -> { value, time, from }, device/<writer key> -> { name } and file/<id> -> { core, blob, sha256 }
function settings_store ({ store, key = null, encryption_key = null }) {
  const emitter = make_emitter()
  const base = new Autobase(store, key, {
    valueEncoding: 'json',
    encryptionKey: encryption_key,
    encrypt: true,
    open: open_view,
    apply: apply_nodes,
    ackInterval: 1000
  })
  base.on('update', () => emitter.emit('update'))
  const api = {
    get key () { return base.key },
    get discovery_key () { return base.discoveryKey },
    get encryption_key () { return base.encryptionKey },
    get writer_key () { return base.local.key },
    get writable () { return base.writable },
    base,
    on: emitter.on,
    off: emitter.off,
    ready,
    close,
    set,
    get,
    read_all,
    add_device,
    remove_device,
    list_devices,
    add_file,
    get_file,
    update: () => base.update()
  }
  return api

  async function ready () { await base.ready() }
  async function close () { await base.close() }
  // value is GVariant text, null means the key was reset, time is when it changed
  async function set (dconf_key, value, time = Date.now()) { await base.append({ type: 'set', key: dconf_key, value, time }) }
  async function get (dconf_key) { return (await base.view.get('dconf/' + dconf_key))?.value || null }
  async function read_all () { return read_prefix(base.view, 'dconf/') }
  async function add_device (writer_key, name) { await base.append({ type: 'add_device', key: to_hex(writer_key), name }) }
  async function remove_device (writer_key) { await base.append({ type: 'remove_device', key: to_hex(writer_key) }) }
  async function list_devices () { return read_prefix(base.view, 'device/') }
  // where a shared file (wallpaper, theme) can be downloaded from
  async function add_file (id, ref) { await base.append({ type: 'file', id, ref }) }
  async function get_file (id) { return (await base.view.get('file/' + id))?.value || null }
}

/***************************************
VIEW
everything apply writes comes from the store autobase passes to open,
so autobase can undo it when it reorders
***************************************/
function open_view (store) {
  return new Hyperbee(store.get('settings'), { keyEncoding: 'utf-8', valueEncoding: 'json', extension: false })
}

async function apply_nodes (nodes, view, host) {
  const batch = view.batch()
  for (const node of nodes) {
    const op = node.value
    const from = b4a.toString(node.from.key, 'hex')
    if (op?.type === 'set') await apply_set({ batch, op, from })
    else if (op?.type === 'add_device') await apply_add_device({ batch, op, host })
    else if (op?.type === 'remove_device' && op.key !== from) await apply_remove_device({ batch, op, host }) // a device never removes itself
    else if (op?.type === 'file') await batch.put('file/' + op.id, op.ref)
  }
  await batch.flush()
}

// newest time wins, same time: the bigger writer key wins, so every device ends up the same
async function apply_set ({ batch, op, from }) {
  const current = await batch.get('dconf/' + op.key)
  if (current && is_older({ time: op.time, from }, current.value)) return
  await batch.put('dconf/' + op.key, { value: op.value, time: op.time, from })
}

async function apply_add_device ({ batch, op, host }) {
  await host.addWriter(b4a.from(op.key, 'hex'), { indexer: true })
  await batch.put('device/' + op.key, { name: op.name })
}

async function apply_remove_device ({ batch, op, host }) {
  const key = b4a.from(op.key, 'hex')
  if (host.removeable(key)) await host.removeWriter(key) // autobase never removes the last indexer
  await batch.del('device/' + op.key)
}

/***************************************
HELPERS
***************************************/
function is_older (a, b) { return a.time < b.time || (a.time === b.time && a.from < b.from) }

function to_hex (key) { return typeof key === 'string' ? key : b4a.toString(key, 'hex') }

async function read_prefix (bee, prefix) {
  const result = {}
  for await (const entry of bee.createReadStream({ gte: prefix, lt: prefix + '\xff' })) result[entry.key.slice(prefix.length)] = entry.value
  return result
}

// the writer key of this device before it joins, sent to the other device when pairing
async function get_writer_key (store) {
  const core = Autobase.getLocalCore(store)
  await core.ready()
  const key = core.key
  await core.close()
  return key
}
